import {sins} from './data.mjs';
import {monster} from './monsters.mjs';
import {decodeScores,readSavedResult,resultProfile,RESULT_KEY} from './state.mjs';
import {downloadShareCard,resultLink} from './share-card.mjs';
const app=document.querySelector('#result-app');
function currentScores(){if(location.hash)return decodeScores(location.hash);try{return readSavedResult(sessionStorage.getItem(RESULT_KEY));}catch{return null;}}
let scores=currentScores();
function radar(values){
 const point=(i,r)=>[210+Math.cos(-Math.PI/2+i*2*Math.PI/7)*r,148+Math.sin(-Math.PI/2+i*2*Math.PI/7)*r];
 const polygon=r=>sins.map((_,i)=>point(i,r).join(',')).join(' ');
 return `<svg class="radar-chart" viewBox="0 0 420 310" role="img" aria-label="Seven-sin radar chart. ${sins.map((s,i)=>`${s.name} ${values[i]} out of 100`).join('; ')}"><g fill="none" stroke="#d2c8be">${[25,50,75,100].map(n=>`<polygon points="${polygon(n)}"/>`).join('')}${sins.map((s,i)=>`<path d="M210 148L${point(i,100).join(' ')}"/>`).join('')}</g><polygon points="${values.map((v,i)=>point(i,v).join(',')).join(' ')}" fill="#9d80c3" fill-opacity=".35" stroke="#79579c" stroke-width="2.5"/>${sins.map((s,i)=>{const [x,y]=point(i,128);return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle" fill="#55444e" font-size="14" font-family="Arial">${s.name}</text>`;}).join('')}</svg>`;
}
function emptyResult(){
 app.innerHTML=`<div class="empty-result">${monster('sloth')}<div class="eyebrow">A LITTLE SOMETHING IS MISSING</div><h1 class="page-title">Your result is<br><em>waiting for you.</em></h1><p>${location.hash?'This result link is incomplete or invalid. Try opening the original link again, or take a fresh quiz.':'Answer the 21 questions to discover your personal seven-sin profile.'}</p><a class="button" href="/#quiz">Take the quiz <span aria-hidden="true">✦</span></a><p class="result-safety">No result has been invented or guessed.</p></div>`;
}
async function copyText(text){
 try{await navigator.clipboard.writeText(text);return true;}catch{
  const input=document.createElement('textarea');input.value=text;input.setAttribute('readonly','');input.style.position='fixed';input.style.top='-1000px';document.body.append(input);input.select();
  try{return document.execCommand('copy');}catch{return false;}finally{input.remove();}
 }
}
function status(text){document.querySelector('#result-status').textContent=text;}
function render(){
 const profile=resultProfile(scores),top=profile.leaders,single=profile.kind==='single',even=profile.kind==='even';
 const name=single?`${top[0].name}.`:even?'Even Ensemble.':'Shared Spotlight.';
 const subtitle=single?top[0].title:even?'All seven tendencies are evenly matched.':top.map(s=>s.name).join(' + ');
 const intro=single?top[0].intro:even?(profile.maximum===0?'None of these statements strongly matched your answers. There is no leading sin to single out.':'Your seven scores match, so there is no single leading sin. Today’s answers call for an ensemble cast.'):'These tendencies share your highest score. Your result keeps the tie, because a shared spotlight tells a better story than a forced winner.';
 const quote=single?top[0].quote:even?'One label? That was never going to be enough.':'Some personalities prefer a shared spotlight.';
 const heading=single?'Meet your little troublemaker.':even?'You contain multitudes.':'A little more than one label.';
 const art=top.map(s=>monster(s.id)).join('');
 const runner=profile.runnerUps.some(s=>scores[sins.indexOf(s)]>0)?`<p class="runner-up"><strong>${single?'Next closest':'Next in the mix'}:</strong> ${profile.runnerUps.map(s=>`${s.name} (${scores[sins.indexOf(s)]}/100)`).join(', ')}. Small score differences are not validated measurements.</p>`:'';
 app.innerHTML=`<header class="result-heading"><span class="eyebrow">YOUR LITTLE REVELATION</span><h1 class="page-title">${heading}</h1><p>${single?'Your strongest tendency in this quiz is '+top[0].name+'.':even?'Seven independent scores. No single winner.':'A tied result, with room for every leading character.'} A playful reflection of your answers today.</p></header><div class="result-layout"><div><div class="sample-card actual-result-card ${single?'':'ensemble-card'}" style="--card:${single?top[0].color:'#D4C5E9'}"><div class="card-heading"><span>SEVEN LITTLE SINS</span><span aria-hidden="true">✦</span></div><div class="sample-label">${single?'YOUR LEADING TENDENCY':even?'ALL SEVEN, EVENLY MATCHED':'JOINT LEADING TENDENCIES'}</div><div class="result-monsters count-${top.length}">${art}</div><h2>${name}</h2><p class="sample-title">${subtitle}</p><blockquote>“${quote}”</blockquote><div class="sample-card-foot">sevendeadlysinstest.xyz</div></div><div class="result-actions"><button type="button" class="button" data-download>Download my card <span aria-hidden="true">✦</span></button><button type="button" class="button secondary" data-copy>Copy result link</button></div><p class="share-note">The PNG shows your leading character${single?'':'s'} without your scores. A result link shares all seven scores. Anyone with the link can view them.</p><p id="result-status" class="result-status" role="status" aria-live="polite"></p><div class="manual-copy" hidden><label for="result-link">Copy this link manually:</label><input id="result-link" type="text" readonly></div></div><section class="profile-panel" aria-labelledby="profile-heading"><h2 id="profile-heading">Your seven-sin profile.</h2><p>Independent scores out of 100. They do not add up to 100. <a href="/results-guide/">How to read your result</a>.</p>${radar(scores)}<div class="score-list">${sins.map((s,i)=>`<div class="score-row"><button type="button" class="score-name" data-character="${s.id}" aria-haspopup="dialog" aria-controls="homepage-dialog">${s.name}</button><div class="score-track" role="meter" aria-label="${s.name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${scores[i]}"><div class="score-fill" style="--card:${s.color};width:${scores[i]}%"></div></div><span>${scores[i]}/100</span></div>`).join('')}</div>${runner}<p class="fine-print">These scores describe your answers, not your character or your standing against other people. They are not population percentiles.</p></section></div><section class="result-reading"><h2>A little context.<br><em>A lot more than a label.</em></h2><p class="result-intro">${intro}</p><div class="reading-grid">${single?`<article class="reading-block"><h3>The good energy.</h3><p>${top[0].strength}</p></article><article class="reading-block"><h3>The little tripwire.</h3><p>${top[0].blind}</p></article>`:top.map(s=>`<article class="reading-block"><h3>${s.name}: ${s.title}</h3><p>${s.strength}</p><a class="quiet-button" href="/sins/${s.id}/">Explore ${s.name.toLowerCase()}</a></article>`).join('')}</div><div class="result-challenge"><span class="eyebrow">YOUR TINY COUNTER-HABIT</span><h3>${single?'A little '+top[0].opposite.toLowerCase()+'.':'Choose one small beginning.'}</h3><p>${single?top[0].challenge:'Pick one habit that felt familiar while answering. Try one small, practical change today. Your score is a conversation starter, not a requirement to change who you are.'}</p>${single?`<a class="quiet-button" href="/sins/${top[0].id}/">Read the full ${top[0].name.toLowerCase()} guide</a>`:''}</div><p class="result-safety">Original entertainment questions, not a validated psychological scale. No diagnosis or moral judgment. Rest, attraction, ambition, and anger are ordinary human experiences.</p><div class="invite-block"><h2>Another little revelation?</h2><p>Retake the quiz, explore the seven characters, or send a friend the quiz.</p><a class="button" href="/?new=1#quiz">Take the quiz again <span aria-hidden="true">✦</span></a><a class="quiet-button" href="/#meet">Meet the whole lineup</a><button type="button" class="quiet-button" data-invite>Copy quiz link for a friend</button></div></section>`;
 document.querySelector('[data-download]').addEventListener('click',async event=>{
  const button=event.currentTarget;button.disabled=true;button.setAttribute('aria-busy','true');status('Creating your PNG card…');
  try{await downloadShareCard(scores);status('Your PNG card is ready. Check your browser’s downloads.');}catch{status('The card could not be created in this browser. You can still copy your result link.');}finally{button.disabled=false;button.removeAttribute('aria-busy');}
 });
 document.querySelector('[data-copy]').addEventListener('click',async()=>{
  const url=resultLink(scores),copied=await copyText(url);
  if(copied){status(location.hostname==='127.0.0.1'||location.hostname==='localhost'?'Result link copied. Local preview links work only on this device.':'Result link copied. It includes all seven scores.');}
  else{document.querySelector('.manual-copy').hidden=false;const input=document.querySelector('#result-link');input.value=url;input.focus();input.select();status('Automatic copy is unavailable. Select and copy the link below.');}
 });
 document.querySelector('[data-invite]').addEventListener('click',async()=>status(await copyText(`${location.origin}/#quiz`)?'Quiz link copied. This invitation does not include your scores.':'Automatic copy is unavailable. Share the quiz page address from your browser.'));
}
if(scores)render();else emptyResult();
window.addEventListener('hashchange',()=>{scores=currentScores();if(scores)render();else emptyResult();app.scrollIntoView({behavior:'instant',block:'start'});});
